from collections import defaultdict
from statistics import median
from .core import ok
from .temporal import union_duration


def _coverage(rows, duration, predicate=lambda r: True):
    if not duration:
        return 0.0
    total = union_duration([row for row in rows if predicate(row)])
    return min(1.0, total/duration)


# Generated by GitHub Copilot - Oct-05-2026
def camera_quality_metrics(rows, duration, suppressed=None):
    """Keep temporal coverage independent from grounded focus and editorial decisions."""
    if duration <= 0 or not rows:
        return {}
    resolved = [row for row in rows if row.get('focus_person') or
                ((row.get('split') or {}).get('left_person') and (row.get('split') or {}).get('right_person'))]
    source = [row for row in rows if row.get('layout') == 'full_frame']
    safe = [row for row in rows if (row.get('crop') or {}).get('safe')]
    known = [row for row in resolved if row.get('focus_person') and row.get('focus_confidence') is not None
             and row.get('camera_evidence_role', 'CONFIRMED_SPEAKER') in {'CONFIRMED_SPEAKER', 'PROBABLE_SPEAKER'}]
    switches = 0
    previous = None
    for row in rows:
        key = (row.get('source_shot_id'), row.get('layout'), row.get('focus_person'),
               (row.get('split') or {}).get('left_person'), (row.get('split') or {}).get('right_person'))
        if previous is not None and previous[0] == key[0] and previous != key:
            switches += 1
        previous = key
    resolved_coverage = _coverage(resolved, duration)
    return {'timeline_temporal_coverage': _coverage(rows, duration),
            'resolved_focus_coverage': resolved_coverage,
            'editorial_decision_coverage': _coverage([row for row in rows if row.get('layout') != 'full_frame'], duration),
            'source_preservation_fraction': _coverage(source, duration),
            'fallback_camera_fraction': _coverage([row for row in source if row.get('fallback_reason') or
                (row.get('decision') or {}).get('fallback_reason') or not row.get('focus_person')], duration),
            'known_speaker_focus_fraction': _coverage(known, duration),
            'safe_crop_coverage': _coverage(safe, duration), 'switch_rate_per_minute': switches * 60 / duration,
            'suppressed_switch_count': suppressed, 'unresolved_focus_fraction': 1.0 - resolved_coverage,
            'focus_coverage_method': 'explicit_focus_person_or_named_split_pair_not_timeline_fill',
            'camera_director_timeline_coverage': _coverage(rows, duration),
            'director_switches_per_minute': switches * 60 / duration}


def _tracking_metrics(vision):
    # Generated by GitHub Copilot - Oct-05-2026
    if vision.get('tracking_metrics'):
        return vision['tracking_metrics']
    observations=vision.get('observations',[])
    tracks=defaultdict(list); per_person=defaultdict(set)
    for o in observations:
        tid=o.get('track_id'); pid=o.get('person_id')
        if tid: tracks[tid].append(o)
        if tid and pid: per_person[pid].add(tid)
    durations=[]
    for rows in tracks.values():
        times=[float(r.get('time',0)) for r in rows]
        durations.append(max(times)-min(times) if times else 0.)
    raw=len(tracks); persistent=len(per_person) or len(vision.get('people',[]))
    face_embedding_tracks=set()
    for tid, rows in tracks.items():
        if any(r.get('face_embedding_available') or r.get('same_person_confidence') is not None for r in rows):
            face_embedding_tracks.add(tid)
    return {
        'raw_track_count': raw,
        'persistent_person_count': persistent,
        'tracks_per_person': {p:len(ts) for p,ts in sorted(per_person.items())},
        'track_fragmentation_ratio': ((raw-persistent)/raw if raw else None),
        'short_track_ratio': (sum(d<1.0 for d in durations)/len(durations) if durations else None),
        'median_track_duration': median(durations) if durations else None,
        'id_switch_count': 'not_measured',
        'reid_merge_count': sum(max(0,len(ts)-1) for ts in per_person.values()),
        'reid_rejected_merge_count': 'not_measured',
        'simultaneous_identity_conflict_count': 'not_measured',
        'tracks_without_face_embedding_fraction': ((raw-len(face_embedding_tracks))/raw if raw else None),
    }


def build_analysis_quality(metadata, transcript, diarization, vision, active_data, shots,
                           semantic, camera_timeline, issues):
    duration = float(metadata.get('duration') or 0)
    words = transcript.get('words', [])
    conf = [w.get('confidence') for w in words if isinstance(w.get('confidence'), (int, float))]
    asr = sum(conf)/len(conf) if conf else None
    speech_span = sum(max(0.0, w['end']-w['start']) for w in words)
    turns = diarization.get('turns', [])
    diarized = sum(max(0.0, t['end']-t['start']) for t in turns)
    diarization_coverage = min(1.0, diarized/speech_span) if speech_span else (0.0 if words else None)
    observations = vision.get('observations', [])
    frames=vision.get('frames',[])
    visual_tracking_coverage = min(1.0, len({o.get('time') for o in observations})/max(1,len(frames))) if frames else 0.0
    active_rows=active_data.get('intervals',[])
    mapping_cov = active_data.get('coverage') if isinstance(active_data.get('coverage'), (int,float)) else 0.0
    active_known=_coverage(active_rows,duration,lambda r:bool(r.get('active_person')) if 'active_person' in r else r.get('state')=='KNOWN_PERSON') if duration else 0.0
    shot_coverage = _coverage(shots, duration)
    semantic_coverage = _coverage(semantic.get('topics', []), duration)
    camera_coverage = _coverage(camera_timeline, duration)
    missing=[]
    if not turns: missing.append('diarization')
    if not observations: missing.append('visual_tracking')
    if not any(r.get('active_person') if 'active_person' in r else r.get('person_id') for r in active_rows): missing.append('active_speaker_known_person')
    if not camera_timeline: missing.append('camera_timeline')
    quality = {
        'measurement_type': 'runtime_measurements_and_explicit_heuristic_proxies',
        'asr': asr,
        'asr_score_is_model_probability_proxy': True,
        'transcription_coverage': _coverage(transcript.get('segments',[]), duration),
        'diarization_availability': bool(turns),
        'diarization_coverage': diarization_coverage,
        'speaker_person_mapping_coverage': mapping_cov,
        'visual_tracking_coverage': visual_tracking_coverage,
        'persistent_identity_coverage': (len({o.get('person_id') for o in observations if o.get('person_id')})/max(1,len({o.get('track_id') for o in observations if o.get('track_id')}))) if observations else 0.0,
        'active_speaker_coverage': active_known,
        'shot_coverage': shot_coverage,
        'semantic_coverage': semantic_coverage,
        'camera_timeline_coverage': camera_coverage,
        'missing_capabilities': missing,
        'quality_issues': issues,
        'warnings': issues,
        **_tracking_metrics(vision),
        **transcript.get('quality_metrics', {}),
        **diarization.get('alignment_metrics', {}),
        **active_data.get('metrics', {}),
        **semantic.get('qa_metrics', {}), **semantic.get('semantic_metrics', {}),
        **semantic.get('topic_quality', {}),
    }
    return ok(quality, 'ok' if words and shot_coverage > 0 and not missing else 'partial')


# Generated by GitHub Copilot - Oct-05-2026
def quality_gate(analysis, cfg=None):
    """Combine observable degradation without hiding unknown or disabled capabilities."""
    cfg=cfg or {}
    quality=analysis.get('analysis_quality') or {}
    issues=[]
    required_missing=[]
    enabled=cfg.get('diarization',{}).get('enabled',True)
    if enabled and not quality.get('diarization_available',quality.get('diarization_availability')):
        required_missing.append('diarization_unavailable')
    if cfg.get('vision',{}).get('enabled',True) and not analysis.get('people_observations'):
        required_missing.append('visual_tracking_unavailable')
    understanding_status = (analysis.get('stage_status') or {}).get('16_understanding', {}).get('status')
    if understanding_status in {'failed', 'blocked', 'unavailable', 'cancelled'}:
        required_missing.append('understanding_unavailable')
    issues.extend({'code':name,'severity':'high'} for name in required_missing)
    flags={
        'active_speaker_unavailable':cfg.get('vision',{}).get('active_speaker',True) and not any(row.get('active_person') if 'active_person' in row else row.get('person_id') for row in analysis.get('active_speaker',[])),
        'fragmented_tracking':(quality.get('micro_track_ratio') or 0)>.5,
        'participant_explosion':len(analysis.get('participants',[]))>50,
        'qa_unresolved':(analysis.get('qa_metrics',{}).get('unresolved_question_count') or 0)>0,
        'semantic_fallbacks':(analysis.get('semantic_metrics',{}).get('semantic_fallback_ratio') or 0)>
                             cfg.get('semantic_analysis',{}).get('fallback_warning_fraction',.1),
        'global_review_unavailable':analysis.get('semantic_metrics',{}).get('global_review_status')=='unavailable',
        'unresolved_camera_focus':quality.get('resolved_focus_coverage') is not None and quality['resolved_focus_coverage']<.5,
        'preview_skipped':not analysis.get('preview_validation',{}).get('verifier_uses_rendered_frames',False),
        'cross_file_references_unresolved':analysis.get('second_curation_package',{}).get('reference_validation',{}).get('status')=='unresolved',
        'primary_theme_unresolved':analysis.get('topic_quality',{}).get('primary_theme_status')=='unresolved_no_qualified_theme',
        'social_output_blocked':(analysis.get('social_output') or {}).get('story_readiness') == 'BLOCKED',
    }
    issues.extend({'code':name,'severity':'medium' if name!='preview_skipped' else 'info'} for name,present in flags.items() if present)
    degraded=any(issue['severity'] in ('high','medium') for issue in issues)
    status='P0_FAIL' if required_missing else 'P1_DEGRADED' if degraded else 'PASS_WITH_WARNINGS' if issues else 'PASS'
    preview = analysis.get('preview_validation') or {}
    technically_verified = preview.get('status') == 'ok' and preview.get('verifier_uses_rendered_frames') is True
    return {'schema_version':'1.0','status':status,'issues':issues,'required_missing_capabilities':required_missing,
            'preview_validated':technically_verified, 'preview_technical_verified':technically_verified,
            'preview_approved':False, 'publication_ready':False,
            'preview_validation_scope':'technical_canary_not_editorial_approval',
            'not_accuracy_certification':True}
